// Parse uploaded training descriptions
const descriptions = $json.descriptions || [];
const storeId = $json.storeId;

return {
  storeId,
  descriptions: descriptions.map(desc => ({
    text: desc,
    wordCount: desc.split(' ').length,
    charCount: desc.length,
    sentences: desc.split('. ').length
  })),
  totalSamples: descriptions.length,
  timestamp: new Date().toISOString()
};

// Parse voice analysis and create profile
const voiceData = $json.body;
let profile = {};

try {
  // Try to extract JSON from response
  const jsonMatch = voiceData.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    profile = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // Fallback if parsing fails
  profile = {
    tone: 'Unknown',
    avgSentenceLength: 15,
    commonPhrases: [],
    ctaStyle: 'Standard',
    keywordFocus: [],
    structure: 'Not analyzed',
    avgWordCount: 200,
    profile_summary: 'Voice analysis pending manual review'
  };
}

return {
  storeId: $json.storeId,
  voiceProfile: {
    ...profile,
    createdAt: new Date().toISOString(),
    status: 'active'
  },
  sampleCount: $json.totalSamples
};

// Generate training report
return {
  success: true,
  message: 'Brand voice profile created successfully',
  report: {
    storeId: $json.storeId,
    profileStatus: 'active',
    voiceProfile: $json.voiceProfile,
    nextSteps: [
      'Use this voice profile when rewriting descriptions',
      'Test with 5-10 products to validate tone',
      'Refine or retrain if needed'
    ],
    usageInstructions: 'Include brandVoiceProfile parameter in rewrite API calls to apply this learned voice',
    createdAt: new Date().toISOString()
  }
};
